  'sod.scopeIbm':       { pt: 'IBM Cloud está fora: o IAM da IBM tem sete roles genéricas e o SoD real dela vive em {n} permissões da infraestrutura clássica, que não são roles.',
                          en: 'IBM Cloud is out of scope: IBM IAM has seven generic roles, and its real SoD lives in {n} classic infrastructure permissions, which are not roles.' },
  'sod.scopeCrossA':    { pt: 'As',                    en: 'The' },
  'sod.scopeCrossB':    { pt: 'regras que cruzam plataformas ficam dentro do mesmo provedor — Entra ID + Azure RBAC, e GCP + Google Workspace. Entre provedores diferentes não há regra.',
                          en: 'cross-platform rules stay within one provider — Entra ID + Azure RBAC, and GCP + Google Workspace. Across different providers there is no rule.' },
