  // ── Cauda: páginas de cloud e componentes diversos ────────────────────────
  'ibm.pageSub':        { pt: 'Referência de roles, plataformas e acessos do IBM Cloud',
                          en: 'IBM Cloud roles, platforms and access, for reference' },
  'ibm.classicDesc':    { pt: '{n} permissões em 6 categorias, não roles',
                          en: '{n} permissions across 6 categories, not roles' },
  'ibm.modelsBody':     { pt: 'O IBM Cloud tem três modelos de acesso: **IAM**, por política granular sobre recurso moderno; **Classic Infrastructure**, por permissão individual em seis categorias (Administrative, Devices, Network, Sales, Security, Software); e **Cloud Foundry**, por Org e Space, para aplicação PaaS.',
                          en: 'IBM Cloud has three access models: **IAM**, granular policy over modern resources; **Classic Infrastructure**, individual permissions across six categories (Administrative, Devices, Network, Sales, Security, Software); and **Cloud Foundry**, by org and space, for PaaS applications.' },
  'gcp.pageSub':        { pt: 'Referência das predefined roles do GCP IAM',
                          en: 'GCP IAM predefined roles, for reference' },
  'gcp.modelBody':      { pt: 'O GCP IAM trabalha com **predefined roles**, que agrupam permissões granulares por serviço. Role de alto nível como **roles/owner** e **roles/iam.admin** só deveria ser atribuída quando não houver alternativa — antes disso, prefira a de menor escopo: Viewer, User ou Invoker.',
                          en: 'GCP IAM works with **predefined roles**, which bundle granular permissions by service. A high-level role such as **roles/owner** or **roles/iam.admin** should only be assigned when nothing narrower will do — before that, reach for Viewer, User or Invoker.' },
  'entra.pageSub':      { pt: 'Referência de roles e permissões', en: 'Roles and permissions, for reference' },
  'entra.apiPermsSub':  { pt: 'Permissões da API do Microsoft Graph, com classificação EAM',
                          en: 'Microsoft Graph API permissions, with EAM classification' },
  'entra.tierNoteSelf': { pt: 'a classificação vem da definição da própria role na fonte, não das ações listadas aqui.',
                          en: 'the classification comes from the role’s own definition at the source, not from the actions listed here.' },
  'home.tagline':       { pt: 'Roles, permissions e policies de 6 provedores de cloud',
                          en: 'Roles, permissions and policies from 6 cloud providers' },
